const credentialDisplayNameContains = 'OpenAI';
// Change only this value to match your Credential display name.
// Nothing below normally needs to be changed.

const root = $input.first().json;
const credentials = root?.data?.credentials ?? root?.credentials ?? [];
const candidates = credentials.filter((item) => {
  const displayName = String(item?.metadata?.displayName ?? '');
  const normalizedDisplayName = displayName.replace(/[\s_-]+/g, '').toLowerCase();
  const fields = Array.isArray(item?.fields) ? item.fields : [];
  return normalizedDisplayName.includes(credentialDisplayNameContains.replace(/[\s_-]+/g, '').toLowerCase()) && fields.some((field) => field?.name === 'apiKey' && field?.secret === true && field?.visible === true);
});
if (candidates.length !== 1) throw new Error(`Expected exactly one OpenAI credential candidate; found ${candidates.length}`);
const selected = candidates[0];
const field = selected.fields.find((item) => item?.name === 'apiKey' && item?.secret === true && item?.visible === true);
return [{ json: { credentialKey: selected.credentialKey, secretNames: [field.name] } }];

const response = $input.first().json;
const resolved = response?.data ?? response;
const apiKey = resolved?.secrets?.apiKey;
if (typeof apiKey !== 'string' || apiKey.length === 0) throw new Error('Resolve response did not contain the expected authorized OpenAI secret field');
return [{ json: { openAiApiKey: apiKey, requestPrompt: 'Respond with exactly: Sekalum connection successful' } }];

const response = $input.first().json;
const body = response?.body ?? response;
const output = Array.isArray(body?.output) ? body.output : [];
const text = output.flatMap((item) => Array.isArray(item?.content) ? item.content : []).map((item) => item?.text).find((value) => typeof value === 'string') ?? '';
const credentialKey = $('Select OpenAI Credential').first().json.credentialKey;
return [{ json: { status: 'completed', credentialKey, openAiHttpStatus: response?.statusCode ?? response?.status ?? null, responseText: text.slice(0, 200), timestamp: new Date().toISOString() } }];
